use ao_reason_workbench::{config::{Actor,NodeSpec},core::{store::Store,runner::Runner},adapters::local::{LocalAo,pump_local}};
fn node()->NodeSpec{NodeSpec{id:"B".into(),address:"local-B/runner".into(),key_hex:"07".repeat(32),slots:1,admitted:true,healthy:true,draining:false,templates:vec!["sum-native-v1".into(),"control-native-v1".into()]}}
fn spin(c:&mut Store,r:&mut Runner,ao:&mut LocalAo,until:impl Fn(&Store)->bool){let deadline=std::time::Instant::now()+std::time::Duration::from_secs(8);while std::time::Instant::now()<deadline {pump_local(c,r,ao,100).unwrap();if until(c){return}std::thread::sleep(std::time::Duration::from_millis(15));}panic!("local loop did not reach expected state");}
#[test]
fn sum_runs_bundled_rust_child_retains_assignment_until_owner_admission(){let t=tempfile::tempdir().unwrap();let mut c=Store::open(&t.path().join("controller.db"),"native",&[node()]).unwrap();let mut r=Runner::open(&t.path().join("runner.db"),"native",node()).unwrap();let mut ao=LocalAo::new(std::path::Path::new(env!("CARGO_BIN_EXE_aw-cli")),&t.path().join("workers")).unwrap();let run=c.dispatch(&Actor::Local("me".into()),"sum-native-v1",100).unwrap();spin(&mut c,&mut r,&mut ao,|c|{let run=c.run(&run.id).unwrap();run.status=="unknown"&&run.detail["verification"]["state"]=="owner_evidence_required"});let observed=c.run(&run.id).unwrap();assert_eq!(observed.detail["report"]["sum"],6);assert!(observed.detail["verification"]["passed"].is_null());assert!(!c.assignment(&run.id,1).unwrap().unwrap().released);assert_eq!(ao.create_count(),1);drop(c);let c=Store::open(&t.path().join("controller.db"),"native",&[node()]).unwrap();assert_eq!(c.run(&run.id).unwrap().detail["report"]["sum"],6);}
#[test]
fn control_approval_and_cancel_retains_assignment_until_owner_evidence(){let t=tempfile::tempdir().unwrap();let actor=Actor::Local("me".into());let mut c=Store::open(&t.path().join("controller.db"),"native",&[node()]).unwrap();let mut r=Runner::open(&t.path().join("runner.db"),"native",node()).unwrap();let mut ao=LocalAo::new(std::path::Path::new(env!("CARGO_BIN_EXE_aw-cli")),&t.path().join("workers")).unwrap();let run=c.dispatch(&actor,"control-native-v1",100).unwrap();spin(&mut c,&mut r,&mut ao,|c|!c.approvals(&actor,&run.id,100).unwrap().is_empty());assert!(!c.assignment(&run.id,1).unwrap().unwrap().released);let p=c.approvals(&actor,&run.id,100).unwrap().remove(0);let mut service=ao_reason_workbench::core::controller::ControlService::new(c,actor.clone());service.call("decide",serde_json::json!({"run_id":run.id,"request_id":p["request_id"],"generation":p["generation"],"scope_hash":p["scope_hash"],"decision_id":"allow_once"}),100).unwrap();let mut c=service.store;for _ in 0..3 {pump_local(&mut c,&mut r,&mut ao,100).unwrap();}c.cancel_at(&actor,&run.id,100).unwrap();spin(&mut c,&mut r,&mut ao,|c|{let run=c.run(&run.id).unwrap();run.status=="cancel_pending"&&run.detail["verification"]["state"]=="owner_evidence_required"});let observed=c.run(&run.id).unwrap();assert_eq!(observed.detail["verification"]["child_exit_code"],2);assert_eq!(observed.detail["verification"]["passed"],false);assert!(!c.assignment(&run.id,1).unwrap().unwrap().released);assert_eq!(ao.live_owned_processes().unwrap(),0);}
#[test]
fn runner_restart_without_observer_is_unknown_and_does_not_spawn_again(){let t=tempfile::tempdir().unwrap();let mut c=Store::open(&t.path().join("controller.db"),"native",&[node()]).unwrap();let mut r=Runner::open(&t.path().join("runner.db"),"native",node()).unwrap();let worker=std::path::Path::new(env!("CARGO_BIN_EXE_aw-cli"));let mut ao=LocalAo::new(worker,&t.path().join("workers")).unwrap();let actor=Actor::Local("me".into());let run=c.dispatch(&actor,"control-native-v1",100).unwrap();spin(&mut c,&mut r,&mut ao,|c|c.run(&run.id).unwrap().session.is_some());drop(r);let mut r=Runner::open(&t.path().join("runner.db"),"native",node()).unwrap();let mut no_observer=LocalAo::new(worker,&t.path().join("workers-new-observer")).unwrap();pump_local(&mut c,&mut r,&mut no_observer,100).unwrap();assert_eq!(c.run(&run.id).unwrap().status,"unknown");assert_eq!(no_observer.create_count(),0);assert!(!c.assignment(&run.id,1).unwrap().unwrap().released);assert!(c.retry(&actor,&run.id,1).is_err());drop(ao);}
